var i=193;var t=[{id:`cooking-193-01`,theoryId:193,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why is baking soda commonly paired with an acidic ingredient?`,ua:`Чому харчову соду часто поєднують із кислим інгредієнтом?`},explanation:{en:`A chemical reaction produces gas that can expand the batter.`,ua:`Хімічна реакція утворює газ, який розпушує тісто.`},options:[{id:`a`,text:{en:`Acid turns soda into yeast cells`,ua:`Кислота перетворює соду на клітини дріжджів`}},{id:`b`,text:{en:`Acid prevents any bubbles from forming`,ua:`Кислота не дає утворюватися бульбашкам`}},{id:`c`,text:{en:`Acid reacts with bicarbonate to release carbon dioxide`,ua:`Кислота реагує з гідрокарбонатом і вивільняє вуглекислий газ`}}],answer:{optionIds:[`c`]}},{id:`cooking-193-02`,theoryId:193,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Baking powder and baking soda are always interchangeable at the same mass.`,ua:`Розпушувач і харчова сода завжди взаємозамінні в однаковій масі.`},explanation:{en:`Baking powder includes acidifying components; replacing it with soda changes the formula.`,ua:`Розпушувач містить кислотні компоненти; заміна содою змінює рецептуру.`},answer:{value:!1}},{id:`cooking-193-03`,theoryId:193,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match leavening systems with their main gas sources.`,ua:`Поєднайте способи розпушування з джерелами газу.`},explanation:{en:`Different leavening methods can coexist but work differently.`,ua:`Різні способи розпушування можуть поєднуватися, проте діють по-різному.`},leftItems:[{id:`l1`,text:{en:`Baking soda plus acid`,ua:`Сода з кислотою`}},{id:`l2`,text:{en:`Yeast fermentation`,ua:`Дріжджове бродіння`}},{id:`l3`,text:{en:`Choux pastry`,ua:`Заварне тісто`}}],rightItems:[{id:`r2`,text:{en:`Microbial carbon dioxide`,ua:`CO₂ від діяльності мікроорганізмів`}},{id:`r3`,text:{en:`Steam expansion`,ua:`Розширення пари`}},{id:`r1`,text:{en:`Chemical carbon dioxide`,ua:`Хімічне утворення CO₂`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-193-04`,theoryId:193,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A soda-leavened cake has a soapy taste. Which recipe issue should you investigate?`,ua:`Кекс із содою має мильний присмак. Яку проблему рецептури перевірити?`},explanation:{en:`Unreacted bicarbonate can cause off-flavors and excess alkalinity.`,ua:`Непрореагована сода може давати сторонній присмак і надмірну лужність.`},options:[{id:`a`,text:{en:`Excess bicarbonate or insufficient acid`,ua:`Надлишок соди або нестачу кислоти`}},{id:`b`,text:{en:`Whether flour was stored in a red container`,ua:`Чи борошно зберігалося в червоній ємності`}},{id:`c`,text:{en:`Whether the baking pan is round`,ua:`Чи кругла форма для випікання`}}],answer:{optionIds:[`a`]}},{id:`cooking-193-05`,theoryId:193,type:`sequence`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Arrange a basic baking-soda batter workflow.`,ua:`Упорядкуйте основні дії для тіста з харчовою содою.`},explanation:{en:`Some chemical leavening starts upon wetting, so timing matters.`,ua:`Частина хімічного розпушування починається після зволоження, тому час важливий.`},steps:[{id:`s2`,text:{en:`Prepare oven and baking pan`,ua:`Підготувати духовку та форму`}},{id:`s4`,text:{en:`Bake promptly according to formula`,ua:`Своєчасно випекти за рецептурою`}},{id:`s1`,text:{en:`Measure dry and wet ingredients`,ua:`Відміряти сухі й рідкі складники`}},{id:`s3`,text:{en:`Combine ingredients according to recipe`,ua:`З’єднати інгредієнти за рецептом`}}],answer:{order:[`s1`,`s2`,`s3`,`s4`]}}];var n={theoryId:193,exercises:t};export{n as default,t as exercises,i as theoryId};